const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const chiangMai = ee.Geometry.Point([98.9808, 18.7897]);
  const bangkok = ee.Geometry.Point([100.5018, 13.7563]);
  const startDate = '2024-03-01';
  const endDate = '2024-04-01';

  // 2. Data Acquisition
  const getAOD = function(point, locationName) {
    // Try MODIS Terra first
    let collection = ee.ImageCollection('MODIS/006/MOD04_3K')
      .filterDate(startDate, endDate)
      .filterBounds(point);

    const count = collection.size().getInfo();
    print(`${locationName} Images: ${count}`);

    // If no data, try MODIS Aqua
    if (count === 0) {
      collection = ee.ImageCollection('MODIS/006/MYD04_3K')
        .filterDate(startDate, endDate)
        .filterBounds(point);
      const count2 = collection.size().getInfo();
      print(`${locationName} Aqua Images: ${count2}`);
      if (count2 === 0) return null;
    }

    // Get AOD_550_Dark_Target_Deep_Blue_Combined band
    // Apply quality flag: bits 4-5 = 2 or 3 (good or very good)
    const qualityMasked = collection.map(function(img) {
      const aod = img.select('AOD_550_Dark_Target_Deep_Blue_Combined');
      const qa = img.select('QA_Flag_550');
      const quality = qa.bitwiseAnd(parseInt('110000', 2)).rightShift(4);
      return aod.updateMask(quality.gte(2).and(quality.lte(3)));
    });

    // Calculate mean AOD
    const meanImage = qualityMasked.mean();

    // Get pixel count and mean value
    const stats = meanImage.reduceRegion({
      reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
      geometry: point,
      scale: 3000,
      maxPixels: 1e9
    });

    return stats;
  };

  // 3. Process both locations
  const cmStats = getAOD(chiangMai, 'Chiang Mai');
  const bkStats = getAOD(bangkok, 'Bangkok');

  // 4. Check for empty collections
  if (!cmStats || !bkStats) {
    print("<answer>C1</answer>");
    return;
  }

  // 5. Extract values
  const cmMean = cmStats.get('AOD_550_Dark_Target_Deep_Blue_Combined_mean').getInfo();
  const cmCount = cmStats.get('AOD_550_Dark_Target_Deep_Blue_Combined_count').getInfo();
  const bkMean = bkStats.get('AOD_550_Dark_Target_Deep_Blue_Combined_mean').getInfo();
  const bkCount = bkStats.get('AOD_550_Dark_Target_Deep_Blue_Combined_count').getInfo();

  print(`Chiang Mai - AOD: ${cmMean ? cmMean.toFixed(4) : 'None'}, Valid Pixels: ${cmCount}`);
  print(`Bangkok - AOD: ${bkMean ? bkMean.toFixed(4) : 'None'}, Valid Pixels: ${bkCount}`);

  // 6. Validation checks
  if (cmCount === 0 || bkCount === 0) {
    print("<answer>C2</answer>");
    return;
  }

  if (cmMean === null || bkMean === null || 
      isNaN(cmMean) || isNaN(bkMean) ||
      cmMean < 0 || bkMean < 0 || 
      cmMean > 5 || bkMean > 5) {
    print("<answer>C3</answer>");
    return;
  }

  // 7. Final comparison (note: AOD unitless, typically 0-1 for clear to hazy)
  print(`AOD Difference (Chiang Mai - Bangkok): ${(cmMean - bkMean).toFixed(4)}`);

  if (cmMean > bkMean) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
